import * as storage from './storage.js';
import {renderQR} from './qr.js';
import {shareNetwork} from './share.js';
import {validateNetwork,makeId,formatDate,esc} from './utils.js';
import {createCameraSession} from './camera.js';
import {isLabMode,buildLabDiagnostic,buildLabText,characterDifferences} from './lab-diagnostics.js';
import {APP_VERSION,VALIDATION_SECTIONS,VALIDATION_FAILURE_CATEGORIES,VALIDATION_STATUS,VALIDATION_STORAGE_KEY,isValidationMode,createChecklist,loadChecklist,saveChecklist,updateChecklistEntry,collectCapabilities,createValidationExport,createReadableReport} from './validation.js';
const root=document.querySelector('#app'),modal=document.querySelector('#modal'),toastEl=document.querySelector('#toast');
const LAB_MODE=isLabMode(location);
const VALIDATION_MODE=isValidationMode(location);
let route=VALIDATION_MODE?'validation':'home',current=null,showSecret=false;
let validationChecklist=loadChecklist();
const camera=createCameraSession();
let cameraViewSequence=0,ocrRunSequence=0,activeOcrController=null,ocrResult=null,processedPreviewUrl=null,photoView='original',ocrErrorMessage='',ocrProgress={status:'Preparando imagen',progress:null},parserResult=null;
let labRecord={ssid:'',password:'',security:'',operator:'',classification:'',observations:'',failureCategories:[],hidePassword:false};
const icons={scan:'▧',manual:'✎'};
function toast(message){if(!message)return;toastEl.textContent=message;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2500);}
function setTab(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===(route==='home'||route==='recent'||route==='settings'?route:'home')));}
function formMarkup(){return `<form id="network-form" class="card page-card" data-origin="manual" data-editing="${current?.id?'true':'false'}"><label class="field"><span>Nombre de la red (SSID)</span><div class="field-control"><span class="field-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 9a14 14 0 0 1 18 0M6.5 12.5a8.5 8.5 0 0 1 11 0M10 16a3.2 3.2 0 0 1 4 0M12 20h.01"/></svg></span><input name="ssid" autocomplete="off" maxlength="64" placeholder="Ej. MiCasa_5G" required value="${esc(current?.ssid||'')}"></div></label><label class="field"><span>Contraseña</span><div class="input-wrap"><span class="field-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="8" cy="15" r="4"/><path d="m11 12 8-8 3 3-2 2-2-2-2 2 2 2-3 3"/></svg></span><input name="password" id="password-input" type="${showSecret?'text':'password'}" autocomplete="new-password" placeholder="${document.querySelector('#security')?.value==='Sin contraseña'?'No necesaria':'Introduce la contraseña'}" value="${esc(current?.password||'')}"><button type="button" data-action="toggle-secret">${showSecret?'Ocultar':'Mostrar'}</button><button type="button" data-action="paste">Pegar</button></div></label><p class="form-hint">Si es tu red actual, copia la contraseña desde Ajustes y pégala aquí.</p><button type="button" class="iphone-help-link" data-action="iphone-help">¿Cómo copiar la contraseña en iPhone?</button><label class="field"><span>Tipo de seguridad</span><div class="field-control"><span class="field-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/></svg></span><select name="security" id="security"><option ${current?.security==='WPA/WPA2'||!current?.security?'selected':''}>WPA/WPA2</option><option ${current?.security==='WPA3'?'selected':''}>WPA3</option><option ${current?.security==='WEP'?'selected':''}>WEP</option><option ${current?.security==='Sin contraseña'?'selected':''}>Sin contraseña</option></select></div></label><label class="field"><span>Nota (opcional)</span><input name="note" maxlength="120" placeholder="Ej. Casa - salón" value="${esc(current?.note||'')}"></label><details><summary class="field-label">Opciones avanzadas</summary><label class="check-row"><input type="checkbox" name="hidden" ${current?.hidden?'checked':''}> Red oculta</label></details><div class="security-note">WPA3 se representa con el formato Wi-Fi estándar WPA. Algunos dispositivos pueden pedir confirmación adicional.</div><button class="primary full" type="submit">Generar QR</button></form>`;}
async function home(){const list=(await storage.getAllNetworks().catch(()=>[])).slice(0,3);document.querySelector('.nav-count').hidden=!list.length;return `<section class="screen home-screen"><div class="home-brand"><div class="home-logo"><svg viewBox="0 0 64 64" aria-hidden="true"><path d="M8 24a38 38 0 0 1 48 0M17 34a24 24 0 0 1 30 0M25 43a11 11 0 0 1 14 0M32 54h.01"/></svg></div><h1>NETLIXY</h1></div><div class="home-actions"><div class="home-action-grid"><button class="action-card" data-go="manual"><span class="card-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 14h3v3h-3zm7 0v3h-3m-4 4h4m3-4v4"/></svg></span><span><strong>Generar QR</strong><small>Introducir datos</small></span></button><button class="action-card" data-go="recent"><span class="card-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v14H4zM2 3h20M8 3v4m8-4v4m-8 5h8m-8 4h6"/></svg></span><span><strong>Redes guardadas</strong><small>Ver redes y notas</small></span></button><button class="action-card" data-go="recent"><span class="card-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12a8 8 0 1 0 2.3-5.7L4 8.5M4 4v4.5h4.5M12 7v5l3.5 2"/></svg></span><span><strong>Recientes</strong><small>Últimas redes guardadas</small></span></button></div></div><section class="home-recent"><div class="recent-header"><h2>Redes recientes</h2><button class="text-button" data-go="recent">Ver todas <span aria-hidden="true">›</span></button></div>${list.length?`<div class="home-network-list">${list.map(n=>`<button class="list-row" data-open="${esc(n.id)}"><span class="row-wifi"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9a14 14 0 0 1 18 0M6.5 12.5a8.5 8.5 0 0 1 11 0M10 16a3.2 3.2 0 0 1 4 0M12 20h.01"/></svg></span><span class="row-info"><strong>${esc(n.ssid)}</strong><span class="note">${esc(n.note||n.security||'Red guardada')}</span></span><span class="arrow">›</span></button>`).join('')}</div>`:`<button class="empty home-empty" data-go="recent"><span class="empty-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9a14 14 0 0 1 18 0M6.5 12.5a8.5 8.5 0 0 1 11 0M10 16a3.2 3.2 0 0 1 4 0M12 20h.01"/></svg></span><strong>Aún no hay redes guardadas</strong><span class="muted">Tus redes aparecerán aquí.</span></button>`}</section></section>`;}
async function recent(){const list=await storage.getAllNetworks();document.querySelector('.nav-count').hidden=!list.length;return `<section class="screen"><div class="recent-header"><div><div class="eyebrow">DATOS LOCALES</div><h1 class="page-heading">Redes guardadas</h1></div>${list.length?'<button class="soft-button" data-action="clear-all">Borrar todo</button>':''}</div>${list.length?`<div class="recent-list">${list.map(n=>`<button class="list-row" data-open="${esc(n.id)}"><span class="row-wifi">⌁</span><span class="row-info"><strong>${esc(n.ssid)}</strong><span class="note">${esc(n.note||n.security||'Red guardada')}</span></span><time>${formatDate(n.createdAt)}</time></button>`).join('')}</div>`:`<div class="empty"><div class="empty-icon">⌁</div><h2>Aún no hay redes guardadas</h2><p class="muted">Las redes que guardes aparecerán aquí.</p><button class="primary" data-go="manual">Generar QR</button></div>`}</section>`;}
function settings(){return `<section class="screen settings-screen"><div class="eyebrow">PREFERENCIAS</div><h1 class="page-heading">Ajustes</h1><div class="settings-label">General</div><div class="card settings-card"><h3><span class="settings-icon">⌂</span> Privacidad local</h3><p>Tus redes y contraseñas se guardan solo en este dispositivo. No se envían a servidores externos.</p></div><div class="settings-label">Datos</div><div class="card settings-card"><h3><span class="settings-icon">◷</span> Redes guardadas</h3><p>Elimina las redes y contraseñas guardadas en este dispositivo.</p><button class="danger full" data-action="clear-all" style="margin-top:14px">Borrar todas las redes</button></div><div class="settings-label">Acerca de</div><div class="card settings-card settings-about"><span class="about-mark">⌁</span><div><h3>Netlixy</h3><p>Versión ${APP_VERSION}</p></div></div></section>`;}
function cameraScreen(){return `<section class="screen camera-screen"><div class="camera-heading"><button class="camera-back" data-action="exit-camera" aria-label="Volver">‹</button><div><h1>Escanear router</h1><p>Enfoca la pegatina del router con los datos del Wi-Fi</p></div></div><div class="camera-viewport"><video id="camera-video" autoplay muted playsinline aria-label="Vista de cámara"></video><div class="camera-guide"><span>Coloca aquí la etiqueta del router</span></div><div class="camera-loading" id="camera-loading">Abriendo cámara…</div></div><div class="camera-controls"><button class="torch-button" data-action="toggle-torch" hidden>⚡ Flash</button><button class="shutter" id="capture-button" data-action="capture" aria-label="Hacer foto" disabled><span></span></button><label class="gallery-button">▧ <span>Seleccionar foto</span><input id="gallery-input" type="file" accept="image/*"></label></div><p class="camera-privacy">🔒 La foto permanece en este dispositivo</p></section>`;}
function cameraErrorScreen(error){const denied=error?.kind==='permission',insecure=error?.kind==='insecure';return `<section class="screen camera-error-screen"><button class="soft-button" data-action="exit-camera">‹ Volver</button><div class="card camera-error-card"><div class="error-symbol">${denied?'◉':'▧'}</div><h1>${denied?'No podemos acceder a la cámara':insecure?'La cámara requiere conexión segura':'No se ha podido abrir la cámara'}</h1><p>${esc(error?.message||'Puedes seleccionar una fotografía existente.')}</p><button class="primary full" data-action="retry-camera">Volver a intentar</button><label class="secondary full file-pick">Seleccionar foto<input id="gallery-input" type="file" accept="image/*"></label></div></section>`;}
function reviewScreen(){const image=camera.getPreviewImage()||camera.getConfirmedImage();return `<section class="screen image-screen"><div class="eyebrow">Captura local</div><h1 class="page-heading">Revisa la foto</h1><p class="muted">Asegúrate de que el nombre Wi-Fi y la contraseña se lean claramente.</p><div class="photo-preview">${image?`<img src="${image.url}" alt="Foto de la etiqueta del router">`:'<p>No hay una foto disponible.</p>'}</div><div class="button-row"><button class="soft-button" data-action="repeat-photo">Repetir foto</button><button class="primary" data-action="confirm-photo">Usar esta foto</button></div></section>`;}
function ocrProgressScreen(){const image=camera.getConfirmedImage();const p=ocrProgress;const hasProgress=Number.isFinite(p.progress);return `<section class="screen ocr-progress-screen"><div class="eyebrow">Procesamiento privado</div><h1 class="page-heading">Analizando imagen</h1><div class="ocr-working"><div class="ocr-thumb">${image?`<img src="${image.url}" alt="Foto del router">`:''}</div><div><strong class="ocr-status">${esc(p.status)}</strong><p>Estamos leyendo la información del router…</p></div></div><div class="ocr-progress-track ${hasProgress?'':'indeterminate'}" id="ocr-progress-track" role="progressbar" aria-label="Progreso del reconocimiento" aria-valuemin="0" aria-valuemax="100" ${hasProgress?`aria-valuenow="${Math.round(p.progress*100)}"`:''}><span id="ocr-progress-fill" style="width:${hasProgress?Math.round(p.progress*100):0}%"></span></div><div class="ocr-progress-caption"><span id="ocr-progress-stage">${esc(p.status)}</span><span id="ocr-progress-value">${hasProgress?`${Math.round(p.progress*100)}%`:''}</span></div><button class="soft-button full" data-action="cancel-ocr">Cancelar</button></section>`;}
function ocrResultScreen(){const photo=camera.getConfirmedImage();const noText=!ocrResult?.rawText?.trim();const showImage=photoView==='processed'&&processedPreviewUrl?processedPreviewUrl:photo?.url;return `<section class="screen ocr-result-screen"><div class="eyebrow">Resultado OCR local</div><h1 class="page-heading">${noText?'No hemos podido leer la etiqueta':'Texto detectado'}</h1>${noText?`<div class="form-intro">Prueba a acercar la cámara, mejorar la iluminación, evitar reflejos y mantener la imagen enfocada.</div>`:''}<div class="photo-preview ocr-result-photo"><img src="${showImage||''}" alt="${photoView==='processed'?'Imagen preparada para OCR':'Fotografía original del router'}"></div><div class="button-row image-switch"><button class="${photoView==='original'?'primary':'soft-button'}" data-action="show-original">Original</button><button class="${photoView==='processed'?'primary':'soft-button'}" data-action="show-processed" ${processedPreviewUrl?'':'disabled'}>Preparada para OCR</button></div>${Number.isFinite(ocrResult?.confidence)?`<div class="confidence-card"><span>Confianza global</span><strong>${ocrResult.confidence.toFixed(1)}%</strong></div>${ocrResult.confidence<60?'<div class="confidence-warning">La lectura puede contener errores. Revisa los datos antes de continuar.</div>':''}`:''}<div class="raw-text-panel"><strong>Texto bruto OCR</strong><pre>${esc(ocrResult?.rawText||'')}</pre></div><label class="field ocr-edit-field"><span>Texto normalizado (editable para pruebas)</span><textarea id="ocr-editable-text" rows="9" spellcheck="false">${esc(ocrResult?.normalizedText||'')}</textarea></label><button class="primary full" data-action="detect-wifi-data">Detectar datos Wi-Fi</button><div class="button-row"><button class="secondary" data-action="copy-ocr-text">Copiar texto</button><button class="soft-button" data-action="repeat-ocr">Repetir OCR</button></div><button class="soft-button full" data-action="change-photo" style="margin-top:10px">Cambiar foto</button></section>`;}
function validationEnvironment(){return collectCapabilities({navigatorObject:navigator,windowObject:window,documentObject:document,userAgent:navigator.userAgent,viewport:{width:window.innerWidth,height:window.innerHeight}});}
function validationScreen(){const env=validationEnvironment();const all=Object.values(validationChecklist);const counts={ok:all.filter(x=>x.status==='ok').length,partial:all.filter(x=>x.status==='partial').length,fail:all.filter(x=>x.status==='fail').length,untested:all.filter(x=>x.status==='untested').length};const rows=VALIDATION_SECTIONS.map(section=>`<section class="validation-section"><h2>${esc(section.title)}</h2>${section.tests.map(name=>{const id=`${section.id}:${name}`,entry=validationChecklist[id];return `<article class="validation-item"><h3>${esc(name)}</h3><label class="field"><span>Estado</span><select data-validation="${esc(id)}" data-key="status">${Object.entries(VALIDATION_STATUS).map(([value,state])=>`<option value="${value}" ${entry.status===value?'selected':''}>${state.label}</option>`).join('')}</select></label><label class="field"><span>Nota corta</span><input data-validation="${esc(id)}" data-key="note" maxlength="180" value="${esc(entry.note)}" placeholder="Observación breve, sin datos Wi-Fi"></label><details data-failure-details="${esc(id)}" ${entry.status==='fail'||entry.status==='partial'?'open':''}><summary>Detalles de incidencia (si procede)</summary><label class="field"><span>Categoría</span><select data-validation="${esc(id)}" data-key="category"><option value="">Seleccionar</option>${VALIDATION_FAILURE_CATEGORIES.map(c=>`<option ${entry.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field"><span>Descripción</span><textarea data-validation="${esc(id)}" data-key="description" rows="2" maxlength="500">${esc(entry.description)}</textarea></label><label class="field"><span>Pasos para reproducir</span><textarea data-validation="${esc(id)}" data-key="steps" rows="2" maxlength="500">${esc(entry.steps)}</textarea></label><label class="field"><span>Esperado</span><textarea data-validation="${esc(id)}" data-key="expected" rows="2" maxlength="300">${esc(entry.expected)}</textarea></label><label class="field"><span>Resultado actual</span><textarea data-validation="${esc(id)}" data-key="actual" rows="2" maxlength="300">${esc(entry.actual)}</textarea></label></details></article>`;}).join('')}</section>`).join('');return `<section class="screen validation-screen"><div class="eyebrow">Solo desarrollo · datos locales</div><div class="validation-mode-badge">🧪 Modo validación</div><h1 class="page-heading">Validación física</h1><p class="muted">Registra las pruebas directamente en el dispositivo. No marques como probado nada que solo hayas comprobado con mocks.</p><div class="validation-summary"><span>🟢 ${counts.ok}</span><span>🟡 ${counts.partial}</span><span>🔴 ${counts.fail}</span><span>⚪ ${counts.untested}</span></div><details class="validation-environment" open><summary>Entorno detectado</summary><p>Host: ${esc(location.hostname)} · HTTPS: ${location.protocol==='https:'?'Sí':'No'} · Modo: Validation</p><p>${esc(env.device)} · ${esc(env.browser)} · ${esc(env.mode)}</p><p>Viewport ${env.viewport.width} × ${env.viewport.height} · standalone ${env.standalone?'sí':'no'}</p><p>getUserMedia ${env.capabilities.getUserMedia?'sí':'no'} · IndexedDB ${env.capabilities.indexedDB?'sí':'no'} · Clipboard ${env.capabilities.clipboard?'sí':'no'} · Web Share ${env.capabilities.webShare?'sí':'no'} · Service Worker ${env.capabilities.serviceWorker?'sí':'no'}</p><small>${esc(env.userAgent)}</small></details>${rows}<div class="validation-actions"><button class="primary full" data-action="validation-export">Exportar validación</button><button class="secondary full" data-action="validation-copy">Copiar informe</button><button class="soft-button full" data-action="validation-reset">Restablecer checklist</button><button class="soft-button full" data-action="validation-exit">Volver a Netlixy</button></div><p class="security-note">No incluyas SSID, contraseñas, fotografías ni texto OCR en notas. La exportación elimina datos Wi-Fi reconocibles y solo contiene campos de validación técnica.</p></section>`;}
function parserConfidence(candidate){if(!candidate)return 'Sin detectar';if(candidate.score>=90)return 'Confianza alta';if(candidate.score>=70)return 'Confianza media';return 'Revisa este dato';}
function parserOperatorSummary(operator){if(operator?.detected){const label=operator.confidence==='high'?'Operador detectado':'Posible operador';return `<div class="operator-hint">${label}: <strong>${esc(operator.detected.name)}</strong>${operator.confidence==='high'?'':` · confianza ${operator.confidence}`}</div>`;}if(operator?.ambiguous&&operator.candidates?.length){return `<div class="operator-hint">Posibles operadores: <strong>${esc(operator.candidates.map(c=>c.name).join(' / '))}</strong> · sin confirmar</div>`;}if(operator?.candidates?.length===1&&operator.confidence==='low'){return `<div class="operator-hint">Posible operador: <strong>${esc(operator.candidates[0].name)}</strong> · confianza baja</div>`;}return '<div class="operator-hint muted">Operador no identificado</div>';}
function parserDevDiagnostics(result){if(!LAB_MODE)return '';const evidence=[...(result?.operator?.evidence||[]),...(result?.operator?.candidates||[]).flatMap(candidate=>(candidate.evidence||[]).map(item=>`${candidate.name}: ${item.reason}`))].map(item=>`<li>${esc(item)}</li>`).join('')||'<li>Sin evidencia de marca</li>';const rules=(result?.profileDiagnostics||[]).map(item=>`<li>${esc(item.profileId)} · ${esc(item.field)} · ${esc(item.ruleId)}: ${item.scoreBefore} → ${item.scoreAfter} (${item.delta > 0 ? '+' : ''}${item.delta})</li>`).join('')||'<li>Sin reglas específicas aplicadas</li>';return `<details class="parser-diagnostics"><summary>Diagnóstico de perfil (desarrollo)</summary><p>Perfil: ${esc(result?.operator?.detected?.id||'no identificado')}</p><strong>Evidencias</strong><ul>${evidence}</ul><strong>Scores antes/después</strong><ul>${rules}</ul></details>`;}
function optionList(name,candidates,selected){const relevant=candidates.filter(c=>c.score>=40).slice(0,5);if(relevant.length<2)return '';return `<label class="field"><span>Hemos encontrado ${relevant.length} opciones</span><select data-parser-choice="${name}"><option value="">Selecciona una opción</option>${relevant.map((c,i)=>`<option value="${i}" ${c.value===selected?'selected':''}>${esc(c.value)}</option>`).join('')}</select></label>`;}
function labBuild(result=parserResult,values=labRecord,hidePassword=values.hidePassword){return buildLabDiagnostic({ocr:ocrResult||{},operatorDetection:result?.operator||{},parser:result||{},expected:{ssid:values.ssid,password:values.password,security:values.security,operator:values.operator},classification:values.classification,observations:values.observations,failureCategories:values.failureCategories,hidePassword});}
function labDiffMarkup(actual,expected){if(!expected)return '';const rows=characterDifferences(actual||'',expected);if(!rows.length)return '<small>Sin diferencias de caracteres.</small>';return `<small>Diferencias (posición · detectado → correcto): ${rows.map(x=>`${x.position}: “${esc(x.actual||'∅')}” → “${esc(x.expected||'∅')}”`).join(' · ')}</small>`;}
function labComparisonMarkup(result,ssidDefault,passDefault){const expected={ssid:labRecord.ssid,password:labRecord.password,security:labRecord.security,operator:labRecord.operator};const detected={ssid:ssidDefault,password:passDefault,security:result?.security?.value,operator:result?.operator?.detected?.id};const c=buildLabDiagnostic({ocr:ocrResult||{},operatorDetection:result?.operator||{},parser:result||{},expected}).comparison;const row=(label,key)=>`<p><strong>${label}:</strong> detectado “${esc(String(c[key].detected??'—'))}” · correcto “${esc(String(c[key].expected??'—'))}” · coincide ${c[key].matches==null?'—':c[key].matches?'sí':'no'} ${key==='ssid'?labDiffMarkup(detected.ssid,expected.ssid):key==='password'?labDiffMarkup(detected.password,expected.password):''}</p>`;return `<h3>Comparación</h3>${row('SSID','ssid')}${row('Contraseña','password')}${row('Seguridad','security')}${row('Operador','operator')}`;}
function labPanel(result,ssidDefault,passDefault){const op=result?.operator,security=result?.security,ssids=result?.ssidCandidates||[],passwords=result?.passwordCandidates||[];const image=ocrResult?.image||{};const candidates=items=>items.length?`<ol>${items.map(c=>`<li><code>${esc(c.value)}</code> · score ${c.score} · ${esc(c.reason||'')} · origen: ${esc(c.sourceLine||'')}</li>`).join('')}</ol>`:'<p>Sin candidatos</p>';return `<details class="lab-panel"><summary>Diagnóstico · modo laboratorio</summary><p class="security-note">Los datos correctos se introducen manualmente tras mirar la etiqueta. Nada se guarda automáticamente.</p><div class="lab-metrics"><span>OCR ${ocrResult?.durationMs??'—'} ms · ${Number.isFinite(ocrResult?.confidence)?ocrResult.confidence.toFixed(1)+'%':'confianza —'}</span><span>SSID ${ssids.length} · contraseña ${passwords.length}</span><span>Top scores ${ssids[0]?.score??'—'} / ${passwords[0]?.score??'—'}</span></div><h3>Imagen</h3><p>${image.sourceWidth??'—'} × ${image.sourceHeight??'—'} px · procesada ${image.processedWidth??'—'} × ${image.processedHeight??'—'} px · orientación EXIF normalizada: ${image.orientationNormalized===true?'sí':image.orientationNormalized===false?'no':'no informada'} · ${(image.originalBytes??0)} bytes</p><h3>OCR · ${esc((ocrResult?.languages||[]).join('+')||'idioma no informado')}</h3><details><summary>Raw text</summary><pre>${esc(ocrResult?.rawText||'')}</pre></details><details><summary>Normalized text</summary><pre>${esc(ocrResult?.normalizedText||'')}</pre></details><h3>Operador</h3><p>${esc(op?.detected?.name||'No identificado')} · familia ${esc(op?.detected?.family||'—')} · confianza ${esc(op?.confidence||'baja')}</p><p>Evidencias: ${esc((op?.evidence||[]).join('; ')||'ninguna')}</p><p>Perfiles considerados: ${esc((op?.candidates||[]).map(x=>`${x.name} (${x.score})`).join(', ')||'ninguno')}</p><h3>Candidatos SSID</h3>${candidates(ssids)}<h3>Candidatos contraseña</h3>${candidates(passwords)}<h3>Seguridad</h3><p>${esc(security?.value||'—')} · ${security?.inferred?'asumida':'detectada'} · ${esc(security?.reason||'sin evidencia')}</p><h3>Perfiles y fusión</h3><p>Aplicados: ${esc((result?.appliedProfiles||[]).join(', ')||'ninguno')}</p><ul>${(result?.profileDiagnostics||[]).map(x=>`<li>${esc(x.profileId)} · ${esc(x.field)} · ${esc(x.ruleId)}: ${x.scoreBefore} → ${x.scoreAfter} (${x.delta>0?'+':''}${x.delta})</li>`).join('')||'<li>Sin reglas de score aplicadas</li>'}</ul><details><summary>Texto entregado al parser</summary><pre>${esc(result?.inputText||ocrResult?.normalizedText||'')}</pre></details><h3>Datos correctos (rellenar mirando la etiqueta)</h3><label class="field"><span>SSID correcto</span><input data-lab="ssid" autocomplete="off" value="${esc(labRecord.ssid)}"></label><label class="field"><span>Contraseña correcta</span><input data-lab="password" autocomplete="off" value="${esc(labRecord.password)}"></label><label class="field"><span>Seguridad correcta</span><select data-lab="security"><option value="">Seleccionar</option>${['WPA/WPA2','WPA3','WEP','Sin contraseña'].map(x=>`<option ${labRecord.security===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Operador correcto (opcional)</span><select data-lab="operator"><option value="">No indicado</option>${['digi','movistar','o2','telefonica','orange','jazztel','vodafone','lowi','unknown'].map(x=>`<option value="${x}" ${labRecord.operator===x?'selected':''}>${x}</option>`).join('')}</select></label><div id="lab-comparison" class="lab-comparison">${labComparisonMarkup(result,ssidDefault,passDefault)}</div><label class="field"><span>Resultado de esta muestra</span><select data-lab="classification"><option value="">Seleccionar</option>${['Correcta sin cambios','Correcta tras revisión','OCR incorrecto','Parser incorrecto','Operador incorrecto','Foto insuficiente','Otro'].map(x=>`<option ${labRecord.classification===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Observaciones</span><textarea data-lab="observations" rows="3" placeholder="Ej. Confundió O con 0 en contraseña">${esc(labRecord.observations)}</textarea></label><fieldset class="lab-failures"><legend>Clasificación de fallos observados</legend>${[['Foto',[['photo.blur','Desenfoque'],['photo.reflection','Reflejo'],['photo.low_light','Poca luz'],['photo.crop','Recorte'],['photo.orientation','Orientación']]],['OCR',[['ocr.character_incorrect','Carácter incorrecto'],['ocr.line_missing','Línea perdida'],['ocr.label_unrecognized','Etiqueta no reconocida'],['ocr.value_fragmented','Valor fragmentado'],['ocr.value_merged','Valor unido a otra línea']]],['Parser',[['parser.ssid_not_detected','SSID no detectado'],['parser.password_not_detected','Contraseña no detectada'],['parser.wrong_candidate','Candidato incorrecto'],['parser.wrong_exclusion','Exclusión incorrecta'],['parser.wrong_score','Score incorrecto'],['parser.wrong_security','Seguridad incorrecta']]],['Operador',[['operator.not_detected','Operador no detectado'],['operator.incorrect','Operador incorrecto'],['operator.ambiguous','Operador ambiguo']]],['UI',[['ui.confusing_review','Revisión confusa'],['ui.candidate_not_visible','Candidato correcto no visible'],['ui.wrong_selection','Selección incorrecta']]]].map(([group,items])=>`<strong>${group}</strong>${items.map(([id,label])=>`<label class="check-row"><input type="checkbox" data-lab-category="${id}" ${labRecord.failureCategories.includes(id)?'checked':''}> ${label}</label>`).join('')}`).join('')}</fieldset><label class="check-row"><input type="checkbox" data-lab="hidePassword" ${labRecord.hidePassword?'checked':''}> Ocultar contraseña en exportación</label><p class="security-note">El JSON/texto puede contener credenciales Wi-Fi y texto OCR sensible. Exporta o copia solo bajo tu responsabilidad.</p><div class="button-row"><button type="button" class="secondary" data-action="lab-export">Exportar diagnóstico</button><button type="button" class="soft-button" data-action="lab-copy">Copiar diagnóstico</button></div></details>`;}
function parserReviewScreen(){const result=parserResult;const ssids=result?.ssidCandidates||[],passwords=result?.passwordCandidates||[];const ssidDefault=ssids.filter(c=>c.score>=70).length>1?'':(ssids[0]?.score>=40?ssids[0].value:'');const passDefault=passwords.filter(c=>c.score>=70).length>1?'':(passwords[0]?.score>=40?passwords[0].value:'');const none=!ssidDefault&&!passDefault;return `<section class="screen parser-screen"><div class="eyebrow">Revisión obligatoria</div><h1 class="page-heading">${none?'No hemos podido identificar los datos':'Datos encontrados'}</h1><p class="muted">${none?'Revisa el texto o introduce los datos manualmente. No hemos inventado ningún valor.':'El parser solo propone los datos. Comprueba y corrige los campos antes de generar el QR.'}</p>${none?'<div class="form-intro">No hemos podido identificar los datos Wi-Fi en el texto leído.</div>':''}${!ssidDefault?'<div class="confidence-warning">No hemos podido identificar el nombre Wi-Fi. Escríbelo manualmente.</div>':''}${!passDefault&&result?.security?.value!=='Sin contraseña'?'<div class="confidence-warning">No hemos podido identificar la contraseña. Revísala en la etiqueta e introdúcela manualmente.</div>':''}${parserOperatorSummary(result?.operator)}<form id="parser-review-form" class="card parser-review-card">${optionList('ssid',ssids,ssidDefault)}<label class="field"><span>Nombre de red · ${parserConfidence(ssids.find(c=>c.value===ssidDefault))}</span><input id="parser-ssid" name="ssid" maxlength="64" autocomplete="off" placeholder="Escribe el nombre Wi-Fi" value="${esc(ssidDefault)}"></label>${optionList('password',passwords,passDefault)}<label class="field"><span>Contraseña · ${parserConfidence(passwords.find(c=>c.value===passDefault))}</span><div class="input-wrap"><input id="parser-password" name="password" type="${showSecret?'text':'password'}" autocomplete="off" placeholder="Escribe la contraseña" value="${esc(passDefault)}"><button type="button" data-action="toggle-parser-secret">${showSecret?'Ocultar':'Mostrar'}</button></div></label><label class="field"><span>Seguridad${result?.security?.inferred?' · asumida':' · detectada'}</span><select name="security"><option ${result?.security?.value==='WPA/WPA2'?'selected':''}>WPA/WPA2</option><option ${result?.security?.value==='WPA3'?'selected':''}>WPA3</option><option ${result?.security?.value==='WEP'?'selected':''}>WEP</option><option ${result?.security?.value==='Sin contraseña'?'selected':''}>Sin contraseña</option></select></label>${result?.security?.inferred?'<p class="security-note">No se identificó el tipo de seguridad. Se propone WPA/WPA2; cámbialo si la etiqueta indica otra cosa.</p>':''}${result?.warnings?.some(w=>w.includes('varios SSID'))?'<div class="confidence-warning">Se encontraron varios nombres de red. Selecciona el que quieras compartir.</div>':''}<details class="parser-diagnostics"><summary>Ver texto OCR</summary><pre>${esc(ocrResult?.rawText||'')}</pre></details>${parserDevDiagnostics(result)}${LAB_MODE?labPanel(result,ssidDefault,passDefault):''}<button class="primary full" type="submit">He revisado los datos · Generar QR</button></form><div class="button-row parser-secondary-actions"><button class="secondary" data-action="back-to-ocr">Revisar texto detectado</button><button class="soft-button" data-action="manual-from-ocr">Introducir manualmente</button></div><button class="soft-button full" data-action="repeat-photo" style="margin-top:10px">Repetir foto</button></section>`;}
function ocrErrorScreen(){const image=camera.getConfirmedImage();return `<section class="screen ocr-error-screen"><div class="eyebrow">OCR local</div><h1 class="page-heading">No se ha podido analizar la imagen</h1><p class="muted">${esc(ocrErrorMessage||'Ha ocurrido un error al leer la fotografía. La imagen sigue disponible en este dispositivo.')}</p>${image?`<div class="ocr-thumb error-thumb"><img src="${image.url}" alt="Foto del router"></div>`:''}<div class="button-row"><button class="primary" data-action="repeat-ocr">Reintentar</button><button class="soft-button" data-action="change-photo">Cambiar foto</button></div><p class="security-note">Si es la primera vez que usas OCR, conecta la aplicación para cargar y guardar localmente sus recursos.</p></section>`;}
function updateOcrProgress(){const status=root.querySelector('.ocr-status'),stage=root.querySelector('#ocr-progress-stage'),value=root.querySelector('#ocr-progress-value'),track=root.querySelector('#ocr-progress-track'),fill=root.querySelector('#ocr-progress-fill');if(status)status.textContent=ocrProgress.status;if(stage)stage.textContent=ocrProgress.status;const known=Number.isFinite(ocrProgress.progress);if(track){track.classList.toggle('indeterminate',!known);if(known)track.setAttribute('aria-valuenow',String(Math.round(ocrProgress.progress*100)));else track.removeAttribute('aria-valuenow');}if(fill)fill.style.width=known?`${Math.round(ocrProgress.progress*100)}%`:'0%';if(value)value.textContent=known?`${Math.round(ocrProgress.progress*100)}%`:'';}
function clearOcrResult(){if(processedPreviewUrl){URL.revokeObjectURL(processedPreviewUrl);processedPreviewUrl=null;}ocrResult=null;parserResult=null;photoView='original';ocrErrorMessage='';}
async function detectWifiData(){const text=root.querySelector('#ocr-editable-text')?.value??ocrResult?.normalizedText??'';try{const {parseRouterLabel}=await import('./router-parser.js');parserResult={...parseRouterLabel({rawText:ocrResult?.rawText||'',normalizedText:text}),inputText:text};showSecret=false;route='parser-review';await render();}catch(error){console.error('[Netlixy parser] Error:',error?.message||error);toast('No se pudieron analizar los datos. Puedes introducirlos manualmente.');}}
async function beginOcr(){const photo=camera.getConfirmedImage();if(!photo){toast('No hay una foto confirmada para analizar.');return;}clearOcrResult();const controller=new AbortController();activeOcrController=controller;const run=++ocrRunSequence;ocrProgress={status:'Preparando imagen',progress:null};route='ocr-progress';await render();try{const {recognizeRouterLabel}=await import('./ocr.js');const result=await recognizeRouterLabel(photo.blob,{signal:controller.signal,onStage:status=>{if(run!==ocrRunSequence)return;ocrProgress={status,progress:null};updateOcrProgress();},onProgress:event=>{if(run!==ocrRunSequence)return;ocrProgress={status:event.status||ocrProgress.status,progress:event.progress};updateOcrProgress();}});if(run!==ocrRunSequence)return;const {processedPreviewBlob,...displayResult}=result;ocrResult=displayResult;processedPreviewUrl=processedPreviewBlob?URL.createObjectURL(processedPreviewBlob):null;route='ocr-result';if(['localhost','127.0.0.1'].includes(location.hostname))console.debug('[Netlixy OCR]',{image:result.image,durationMs:result.durationMs,confidence:result.confidence,languages:result.languages});await render();}catch(error){if(error?.name==='AbortError'||run!==ocrRunSequence)return;console.error('[Netlixy OCR] Error visible:',error?.message||error);ocrErrorMessage=navigator.onLine===false?'No se pudieron cargar los recursos OCR locales. Conéctate una vez para preparar el reconocimiento offline.':'Ha ocurrido un error al cargar o ejecutar el reconocimiento local. La fotografía no se ha enviado a ningún servicio.';route='ocr-error';await render();}finally{if(run===ocrRunSequence)activeOcrController=null;}}
function cancelOcr(){ocrRunSequence++;activeOcrController?.abort();activeOcrController=null;clearOcrResult();ocrProgress={status:'Preparando imagen',progress:null};route='image-review';render();}
function preparedScreen(){const image=camera.getConfirmedImage();return `<section class="screen image-screen"><div class="badge">Imagen confirmada</div><h1 class="page-heading">Imagen preparada</h1><p class="muted">La fotografía está lista para analizar.</p><div class="photo-preview confirmed-preview">${image?`<img src="${image.url}" alt="Fotografía preparada de la etiqueta del router">`:'<p>La imagen ya no está disponible. Selecciona otra fotografía.</p>'}</div><p class="camera-privacy">🔒 La imagen permanece en este dispositivo</p><div class="button-row"><button class="soft-button" data-action="change-photo">Cambiar foto</button><button class="primary" data-action="camera-home">Volver al inicio</button></div></section>`;}
async function startCameraView(){const token=++cameraViewSequence;const video=root.querySelector('#camera-video');if(!video)return;const result=await camera.open(video);if(token!==cameraViewSequence)return;if(route!=='camera'){camera.stop();return;}if(!result.ok){document.body.classList.remove('camera-mode');root.innerHTML=cameraErrorScreen(result);return;}const loading=root.querySelector('#camera-loading');if(loading)loading.hidden=true;const captureButton=root.querySelector('#capture-button');if(captureButton)captureButton.disabled=false;const torchButton=root.querySelector('[data-action="toggle-torch"]');if(torchButton)torchButton.hidden=!camera.supportsTorch();}
function qrScreen(){return `<section class="screen qr-screen"><div class="subpage-heading"><button class="back-button" data-go="home" aria-label="Volver a Inicio">‹</button><h1>QR generado</h1><span></span></div><div class="qr-feature-card"><div class="qr-box" id="qr-stage"></div><div class="ssid-title">${esc(current.ssid)}</div><div class="qr-security">${esc(current.security)}${current.hidden?' · Red oculta':''}</div>${current.note?`<p class="qr-note">${esc(current.note)}</p>`:''}<div class="secret-display"><span id="secret-text">${current.password?(showSecret?esc(current.password):'••••••••'):'Sin contraseña'}</span>${current.password?`<button data-action="toggle-result-secret">${showSecret?'Ocultar':'Mostrar'}</button><button data-action="copy-password">Copiar contraseña</button>`:''}</div><div class="qr-success"><span aria-hidden="true">✓</span> QR generado correctamente</div></div><div class="button-row qr-actions"><button class="secondary" data-action="save">Guardar</button><button class="secondary" data-action="share">Compartir</button><button class="copy-data-button" data-action="copy-data"><span aria-hidden="true">▤</span> Copiar datos</button></div><button class="soft-button full" data-action="another">Generar otro QR</button></section>`;}
async function detail(id){const n=await storage.getNetwork(id);if(!n){route='recent';return render();}current=n;const html=`<section class="screen"><button class="soft-button" data-go="recent">‹ Mis redes recientes</button><div class="card page-card"><div class="eyebrow">Red guardada</div><h1 class="page-heading" style="overflow-wrap:anywhere">${esc(n.ssid)}</h1><div class="detail-line"><span>Nota</span><strong>${esc(n.note||'Sin nota')}</strong></div><div class="detail-line"><span>Contraseña</span><strong>${n.password?esc(showSecret?n.password:'••••••••'):'Sin contraseña'} ${n.password?`<button class="soft-button" data-action="toggle-detail-secret" style="padding:5px 8px;font-size:11px">${showSecret?'Ocultar':'Mostrar'}</button>`:''}</strong></div><div class="detail-line"><span>Seguridad</span><strong>${esc(n.security)}</strong></div><div class="detail-line"><span>Creada</span><strong>${formatDate(n.createdAt)}</strong></div><div class="qr-box detail-qr" id="qr-detail"></div><div class="button-row"><button class="secondary" data-action="copy-password">Copiar contraseña</button><button class="primary" data-action="share">Compartir QR</button></div><button class="soft-button full" data-action="regenerate" style="margin-top:10px">Volver a generar QR</button><div class="button-row" style="margin-top:10px"><button class="soft-button" data-action="edit">Editar datos</button><button class="soft-button" data-action="edit-note">Editar nota</button></div><button class="danger full" data-action="delete" style="margin-top:10px">Eliminar red</button></div></section>`;root.innerHTML=html;renderQR(root.querySelector('#qr-detail'),n,220);}
async function render(){setTab();if(route==='validation'){document.body.classList.remove('camera-mode');root.innerHTML=validationScreen();return;}if(route==='recent'){root.innerHTML=await recent();return;}if(route==='settings'){root.innerHTML=settings();return;}if(route==='scan')route='camera';if(route==='camera'){document.body.classList.add('camera-mode');root.innerHTML=cameraScreen();startCameraView().catch(error=>{console.error(error);document.body.classList.remove('camera-mode');root.innerHTML=cameraErrorScreen({kind:'unavailable',message:'No se ha podido abrir la cámara. Puedes seleccionar una fotografía existente.'});});return;}document.body.classList.remove('camera-mode');if(route==='image-review'){root.innerHTML=reviewScreen();return;}if(route==='image-prepared'){root.innerHTML=preparedScreen();return;}if(route==='ocr-progress'){root.innerHTML=ocrProgressScreen();return;}if(route==='ocr-result'){root.innerHTML=ocrResultScreen();return;}if(route==='parser-review'){root.innerHTML=parserReviewScreen();return;}if(route==='ocr-error'){root.innerHTML=ocrErrorScreen();return;}if(route==='manual'||route==='mine'){route='manual';root.innerHTML=`<section class="screen form-screen"><div class="subpage-heading"><button class="back-button" data-go="home" aria-label="Volver a Inicio">‹</button><h1>Generar QR</h1><span></span></div>${formMarkup()}</section>`;return;}if(route==='qr'){root.innerHTML=qrScreen();renderQR(root.querySelector('#qr-stage'),current,290);return;}if(route==='detail'){return detail(current.id);}root.innerHTML=await home();}
function go(next){if(route==='ocr-progress'&&next!=='ocr-progress'){ocrRunSequence++;activeOcrController?.abort();activeOcrController=null;}if(route==='camera'&&next!=='camera'){cameraViewSequence++;camera.stop();}if(['image-review','image-prepared','ocr-progress','ocr-result','parser-review','ocr-error'].includes(route)&&!['image-review','image-prepared','ocr-progress','ocr-result','parser-review','ocr-error'].includes(next)){camera.discardReview();camera.clearConfirmedImage();clearOcrResult();}route=next==='mine'?'manual':next;current=route==='manual'?null:current;showSecret=false;render().then(()=>root.focus({preventScroll:true}));}
function closeModal(){modal.close();modal.innerHTML='';}
function readLabFields(){if(!LAB_MODE)return labRecord;for(const field of root.querySelectorAll('[data-lab]')){const key=field.dataset.lab;labRecord[key]=field.type==='checkbox'?field.checked:field.value;}labRecord.failureCategories=[...root.querySelectorAll('[data-lab-category]:checked')].map(field=>field.dataset.labCategory);return labRecord;}
function updateLabComparison(){if(!LAB_MODE||route!=='parser-review')return;readLabFields();const box=root.querySelector('#lab-comparison');if(!box)return;const ssids=parserResult?.ssidCandidates||[],passwords=parserResult?.passwordCandidates||[];const s=ssids.filter(c=>c.score>=70).length>1?'':(ssids[0]?.score>=40?ssids[0].value:'');const p=passwords.filter(c=>c.score>=70).length>1?'':(passwords[0]?.score>=40?passwords[0].value:'');box.innerHTML=labComparisonMarkup(parserResult,s,p);}
async function labCopy(){readLabFields();const data=labBuild();try{await navigator.clipboard.writeText(buildLabText(data));toast('Diagnóstico copiado al portapapeles.');}catch{toast('No se pudo acceder al portapapeles.');}}
function labExport(){readLabFields();const data=labBuild();if(!window.confirm('Este archivo contiene los datos Wi-Fi que has introducido para la prueba. Compártelo solo si sabes lo que contiene.'))return;const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='netlixy-diagnostic-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Diagnóstico exportado.');}
function ask({title,body,placeholder='',value='',confirm='Guardar',danger=false,onConfirm}){modal.innerHTML=`<h2>${title}</h2><p>${body}</p>${placeholder?`<label class="field"><span>Nota (opcional)</span><input id="modal-input" maxlength="120" placeholder="${esc(placeholder)}" value="${esc(value)}"></label>`:''}<div class="button-row"><button class="soft-button" data-modal-cancel>Cancelar</button><button class="${danger?'danger':'primary'}" data-modal-confirm>${confirm}</button></div>`;modal.showModal();const input=modal.querySelector('#modal-input');if(input)setTimeout(()=>input.focus(),50);modal.querySelector('[data-modal-cancel]').onclick=closeModal;modal.querySelector('[data-modal-confirm]').onclick=async()=>{await onConfirm(input?.value??'');closeModal();};}
async function copyTextToClipboard(text){if(typeof navigator.clipboard?.writeText==='function'){try{await navigator.clipboard.writeText(text);return;}catch{}}const field=document.createElement('textarea');field.value=text;field.setAttribute('aria-hidden','true');field.style.position='fixed';field.style.opacity='0';field.style.pointerEvents='none';document.body.append(field);field.focus();field.select();let copied=false;try{copied=document.execCommand('copy');}finally{field.remove();}if(!copied)throw new Error('Clipboard unavailable');}async function collectValidationSecrets(){const saved=await storage.getAllNetworks().catch(()=>[]);return [...saved.flatMap(n=>[n.ssid,n.password]),current?.ssid,current?.password,parserResult?.ssid?.value,parserResult?.password?.value,...(parserResult?.ssidCandidates||[]).map(c=>c.value),...(parserResult?.passwordCandidates||[]).map(c=>c.value)].filter(Boolean);}
async function exportValidation(){const secrets=await collectValidationSecrets();const report=createValidationExport({checklist:validationChecklist,environment:validationEnvironment(),secrets});const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`netlixy-validacion-${new Date().toISOString().replace(/[:.]/g,'-')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Informe técnico exportado.');}
async function copyValidationReport(){const secrets=await collectValidationSecrets();const text=createReadableReport({checklist:validationChecklist,environment:validationEnvironment(),secrets});try{await navigator.clipboard.writeText(text);toast('Informe copiado.');}catch{toast('No se pudo copiar. Comprueba el permiso del portapapeles.');}}
function updateValidationField(field){const id=field.dataset.validation,key=field.dataset.key;if(!id||!key)return;try{validationChecklist=updateChecklistEntry(validationChecklist,id,{[key]:field.value});saveChecklist(validationChecklist);const detail=root.querySelector(`[data-failure-details="${CSS.escape(id)}"]`);if(detail&&(key==='status'))detail.open=field.value==='fail'||field.value==='partial';const all=Object.values(validationChecklist);const summary=root.querySelector('.validation-summary');if(summary)summary.innerHTML=`<span>🟢 ${all.filter(x=>x.status==='ok').length}</span><span>🟡 ${all.filter(x=>x.status==='partial').length}</span><span>🔴 ${all.filter(x=>x.status==='fail').length}</span><span>⚪ ${all.filter(x=>x.status==='untested').length}</span>`;}catch(error){console.error('[Netlixy validation]',error);toast('No se pudo guardar este resultado local.');}}
function savePrompt(){ask({title:current.id?'Guardar cambios':'Guardar red',body:current.id?'Confirma la nota identificativa para actualizar esta red.':'¿De dónde es esta red?',placeholder:'Ej. Casa cliente - salón',value:current.note||'',confirm:current.id?'Guardar cambios':'Guardar red',onConfirm:async note=>{const now=new Date().toISOString();const saved={...current,id:current.id||makeId(),note:note.trim(),createdAt:current.createdAt||now,updatedAt:now,origin:current.origin||'manual'};await storage.saveNetwork(saved);current=saved;toast('Red guardada en este dispositivo.');document.querySelector('.nav-count').hidden=false;}});}
async function clickAction(action,button){if(action==='validation-export'){await exportValidation();return;}if(action==='validation-copy'){await copyValidationReport();return;}if(action==='validation-reset'){if(window.confirm('Restablecer todas las pruebas a “Sin probar” y borrar las notas locales?')){validationChecklist=createChecklist();saveChecklist(validationChecklist);await render();}return;}if(action==='validation-exit'){route='home';await render();return;}if(action==='lab-export'){labExport();return;}if(action==='lab-copy'){labCopy();return;}if(action==='exit-camera'){camera.stop();camera.discardReview();go('home');return;}if(action==='capture'){button.disabled=true;try{await camera.capture();route='image-review';await render();}catch(error){toast(error.message||'No se pudo capturar la foto.');const b=root.querySelector('#capture-button');if(b)b.disabled=false;}return;}if(action==='repeat-photo'){if(['parser-review','ocr-result','ocr-error'].includes(route)){clearOcrResult();camera.clearConfirmedImage();route='camera';await render();}else{camera.discardReview();go('camera');}return;}if(action==='confirm-photo'){try{if(!camera.getConfirmedImage())camera.confirmImage();await beginOcr();}catch(error){toast(error.message);}return;}if(action==='cancel-ocr'){cancelOcr();return;}if(action==='repeat-ocr'){await beginOcr();return;}if(action==='detect-wifi-data'){await detectWifiData();return;}if(action==='back-to-ocr'){route='ocr-result';await render();return;}if(action==='manual-from-ocr'){clearOcrResult();camera.clearConfirmedImage();go('manual');return;}if(action==='toggle-parser-secret'){showSecret=!showSecret;const input=root.querySelector('#parser-password');if(input)input.type=showSecret?'text':'password';button.textContent=showSecret?'Ocultar':'Mostrar';return;}if(action==='show-original'){photoView='original';render();return;}if(action==='show-processed'){if(processedPreviewUrl){photoView='processed';render();}return;}if(action==='copy-ocr-text'){const text=root.querySelector('#ocr-editable-text')?.value||'';try{await navigator.clipboard.writeText(text);toast('Texto copiado.');}catch{toast('No se pudo copiar el texto. Puedes seleccionarlo manualmente.');}return;}if(action==='change-photo'){clearOcrResult();camera.clearConfirmedImage();route='camera';await render();return;}if(action==='camera-home'){camera.stop();camera.clearConfirmedImage();camera.discardReview();go('home');return;}if(action==='retry-camera'){route='camera';await render();return;}if(action==='toggle-torch'){const enabled=await camera.toggleTorch();button.classList.toggle('torch-on',enabled);button.textContent=enabled?'⚡ Flash activado':'⚡ Flash';if(!enabled)toast('El flash no está disponible en esta cámara.');return;}if(action==='toggle-secret'){showSecret=!showSecret;const i=document.querySelector('#password-input');i.type=showSecret?'text':'password';button.textContent=showSecret?'Ocultar':'Mostrar';return;}if(action==='paste'){try{document.querySelector('#password-input').value=await navigator.clipboard.readText();toast('Contraseña pegada.');}catch{toast('No se pudo acceder al portapapeles. Mantén pulsado el campo y elige Pegar.');}return;}if(action==='iphone-help'){ask({title:'Copiar la contraseña en iPhone',body:'1. Abre Ajustes.<br>2. Entra en Wi-Fi.<br>3. Pulsa el botón de información de tu red.<br>4. Pulsa Contraseña.<br>5. Identifícate con Face ID o código.<br>6. Copia la contraseña.<br>7. Vuelve a Netlixy y pégala.',confirm:'Entendido',onConfirm:()=>{}});return;}if(action==='toggle-result-secret'||action==='toggle-detail-secret'){showSecret=!showSecret;render();return;}if(action==='copy-data'){const details=['SSID: '+current.ssid,'Contraseña: '+(current.password||'Sin contraseña'),'Seguridad: '+current.security].join(String.fromCharCode(10));try{await copyTextToClipboard(details);toast('Datos copiados.');}catch{toast('No se pudieron copiar los datos. Mantén pulsado para copiar.');}return;}if(action==='copy-password'){if(!current?.password){toast('Esta red no tiene contraseña.');return;}try{await navigator.clipboard.writeText(current.password);toast('Contraseña copiada.');}catch{toast('No se pudo copiar; selecciona la contraseña para copiarla.');}return;}if(action==='share'){toast(await shareNetwork(current,root.querySelector('svg')));return;}if(action==='save'){savePrompt();return;}if(action==='another'){go('home');return;}if(action==='regenerate'){route='qr';render();return;}if(action==='edit'){route='manual';await render();return;}if(action==='edit-note'){ask({title:'Editar nota',body:'Añade una referencia para identificar esta red.',placeholder:'Ej. Casa cliente - salón',value:current.note||'',confirm:'Guardar nota',onConfirm:async note=>{current.note=note.trim();current.updatedAt=new Date().toISOString();await storage.saveNetwork(current);toast('Nota actualizada.');route='detail';await render();}});return;}if(action==='delete'){ask({title:'Eliminar esta red',body:'Se borrarán el SSID, la contraseña y la nota guardados. Esta acción no se puede deshacer.',confirm:'Eliminar',danger:true,onConfirm:async()=>{await storage.deleteNetwork(current.id);current=null;route='recent';toast('Red eliminada.');await render();}});return;}if(action==='clear-all'){ask({title:'Borrar todas las redes',body:'Se eliminarán todas las redes, contraseñas y notas guardadas en este dispositivo. Esta acción no se puede deshacer.',confirm:'Borrar todo',danger:true,onConfirm:async()=>{await storage.clearNetworks();current=null;route='recent';toast('Historial borrado.');await render();}});return;}}
root.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){clickAction(action.dataset.action,action);return;}const goButton=e.target.closest('[data-go]');if(goButton){go(goButton.dataset.go);return;}const open=e.target.closest('[data-open]');if(open){current={id:open.dataset.open};route='detail';render();return;}});
document.querySelector('.bottom-nav').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)go(b.dataset.tab==='scan'?'scan':b.dataset.tab);});document.querySelector('.topbar').addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)go(b.dataset.go);});
root.addEventListener('input',e=>{const validation=e.target.closest('[data-validation]');if(validation)updateValidationField(validation);if(e.target.closest('[data-lab]'))updateLabComparison();});root.addEventListener('change',e=>{const validation=e.target.closest('[data-validation]');if(validation)updateValidationField(validation);if(e.target.closest('[data-lab]'))updateLabComparison();});
root.addEventListener('change',e=>{const choice=e.target.closest('[data-parser-choice]');if(!choice)return;const candidates=choice.dataset.parserChoice==='ssid'?parserResult?.ssidCandidates:parserResult?.passwordCandidates;const candidate=candidates?.filter(c=>c.score>=40).slice(0,5)[Number(choice.value)];const input=root.querySelector(choice.dataset.parserChoice==='ssid'?'#parser-ssid':'#parser-password');if(input&&candidate)input.value=candidate.value;});
root.addEventListener('change',async e=>{if(e.target.id!=='gallery-input')return;const file=e.target.files?.[0];e.target.value='';if(!file)return;try{await camera.selectImage(file);route='image-review';await render();}catch(error){toast(error.message||'No se pudo abrir esta imagen.');}});
root.addEventListener('submit',async e=>{if(e.target.id==='parser-review-form'){e.preventDefault();const data=new FormData(e.target);const net={ssid:String(data.get('ssid')||'').trim(),password:String(data.get('password')||''),security:String(data.get('security')||'WPA/WPA2'),hidden:false,origin:'router_scan',source:'router_scan'};const error=validateNetwork(net);if(error){toast(error);return;}current=net;if(LAB_MODE)readLabFields();showSecret=false;route='qr';await render();return;}if(e.target.id!=='network-form')return;e.preventDefault();const form=e.target,data=new FormData(form);const net={ssid:String(data.get('ssid')||'').trim(),password:String(data.get('password')||''),security:String(data.get('security')||'WPA/WPA2'),hidden:data.has('hidden'),note:String(data.get('note')||'').trim(),origin:form.dataset.origin};const error=validateNetwork(net);if(error){toast(error);return;}current={...(form.dataset.editing==='true'?current:{}),...net};showSecret=false;route='qr';await render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){cameraViewSequence++;camera.stop();}else if(route==='camera')startCameraView().catch(()=>{});});window.addEventListener('pagehide',()=>camera.stop());window.addEventListener('load',()=>{render().catch(err=>{console.error(err);root.innerHTML=`<div class="card">No se pudo iniciar el almacenamiento local. ${esc(err.message)}</div>`;});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js',{scope:'./'}).catch(err=>console.warn('SW no disponible',err));});
